node -e "
const CANNON = require('/tmp/cannon-es.cjs');
const carLength = 5.0; // stretched
const carWidth = 2.2;  // wider
const carHeight = 1.8; // taller
const scaleL = carLength / 4.20;
const scaleW = carWidth / 1.80;
const scaleH = carHeight / 1.45;

const cabin = new CANNON.Body({
  mass: 650,
  shape: new CANNON.Box(new CANNON.Vec3(1.10 * scaleL, 0.38 * scaleH, 0.85 * scaleW))
});
console.log('Cabin half-extents:', cabin.shapes[0].halfExtents);
"

